using Chameleon.Interfaces.App.Automation.ExternalScript;
using Microsoft.Playwright;
using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public class GoogleCTRClickThroughExternalScript : IExternalScript
{
    public async Task Run(IBrowserContext context, IDictionary<string, string> args)
    {

	var page = context.Pages[^1] ?? await context.NewPageAsync();

        try
        {
            string keyword = args["keyword"];
            string targetUrl = args["targetUrl"];
            int pagesCount;
            if (!Int32.TryParse(args["pagescount"], out pagesCount))
            {
                throw new ArgumentException("Argument <pagescount> is not valid");
            }
            int timeout;
            if (!Int32.TryParse(args["timeout"], out timeout))
            {
                throw new ArgumentException("Argument <timeout> is not valid");
            }

            // Convert to miliseconds
            timeout *= 1000;

            // Go to Google
            await page.GotoAsync("https://www.google.com");

            var searchInput = page.Locator("//*[@id='APjFqb']");

            // Put the keyword into a search bar
            await searchInput.FillAsync(keyword);
            await searchInput.PressAsync("Enter");

            // Wait for results to load
            await page.WaitForLoadStateAsync(LoadState.DOMContentLoaded);

            bool found = false;
            for (int i = 0; i < pagesCount && !found; i++)
            {
                // Wait for search results
                await page.WaitForSelectorAsync("a[href]");

                // Look for the target URL in the search results
                var links = await page.Locator("a[href]").ElementHandlesAsync();
                foreach (var link in links)
                {
                    var href = await link.GetAttributeAsync("href");
                    if (href != null && href.Contains(targetUrl))
                    {
                        await link.ClickAsync();
                        found = true;
                        break;
                    }
                }

                var nextPage = page.Locator("//*[@id='botstuff']/div/div[4]/div[4]/a[1]");
                // If not found, go to the next page
                if (!found && await nextPage.IsVisibleAsync())
                {
                    await nextPage.ClickAsync();
                    await page.WaitForLoadStateAsync(LoadState.DOMContentLoaded);
                }
            }

            // If the target URL was found, look for another internal link and click it
            if (found)
            {
                await page.WaitForLoadStateAsync(LoadState.DOMContentLoaded);
                var internalLinks = await page.Locator($"a[href*='{targetUrl}'], a[href^='/']").ElementHandlesAsync();
                if (internalLinks.Count > 0)
                {
                    await internalLinks[0].ClickAsync();
               }
            }
        }
        catch (Exception ex)
        {
            // Event handler for dialogs
            page.Dialog += async (_, dialog) =>
            {
                Console.WriteLine($"Dialog message: {dialog.Message}");
            };

            await page.EvaluateAsync("(() => {alert('" + ex.Message + "');})();");
			await Task.Delay(-1);
        }
    }
}

using Chameleon.Interfaces.App.Automation.ExternalScript;
using Microsoft.Playwright;
using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Linq;

public class KeepGmailAliveExternalScript : IExternalScript
{
    public async Task Run(IBrowserContext context, IDictionary<string, string> args)
    {
        var page = context.Pages[^1] ?? await context.NewPageAsync();
        try
        {
            // Navigate to Gmail
            await page.GotoAsync("https://mail.google.com/");
            await page.WaitForLoadStateAsync(LoadState.DOMContentLoaded);

		try
		{
			// Wait for the element to be visible
			await page.WaitForSelectorAsync("//*[@id='gb']/div[2]/div[2]", new PageWaitForSelectorOptions
			{
				Timeout = 10000, // Timeout in milliseconds (10 seconds)
				State = WaitForSelectorState.Visible // Wait until the element is visible
			});
		}
		catch (TimeoutException)
            {
                throw new Exception("User is not logged in to Gmail.");
            }
            await page.WaitForSelectorAsync("tr.zA");
            // Get all email rows
            var emailRows = await page.QuerySelectorAllAsync("tr.zA");
            if (emailRows.Count <= 0)
            {
                throw new Exception("No emails found.");
            }
            // Select a random email and click it
            var randomIndex = new Random().Next(emailRows.Count);
            await emailRows[randomIndex].ClickAsync();
            // Wait for a few seconds to simulate reading the email
            await Task.Delay(5000);
        }
        catch (Exception ex)
        {
            // Event handler for dialogs
            page.Dialog += async (_, dialog) =>
            {
                Console.WriteLine($"Dialog message: {dialog.Message}");
            };
            await page.EvaluateAsync("(() => {alert('" + ex.Message + "');})();");
            await Task.Delay(-1);
        }
    }
}
